import{_ as t}from"./chunks/11-settings.B_GZgwvL.js";import{_ as a,o as i,c as s,a2 as d}from"./chunks/framework.DUZafPzB.js";const g=JSON.parse('{"title":"Agent 配置与更新","description":"","frontmatter":{},"headers":[],"relativePath":"zh/ops/agent.md","filePath":"zh/ops/agent.md","lastUpdated":1793949581000}'),o={name:"zh/ops/agent.md"};function n(h,e,l,c,r,p){return i(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="agent-配置与更新" tabindex="-1">Agent 配置与更新 <a class="header-anchor" href="#agent-配置与更新" aria-label="Permalink to &quot;Agent 配置与更新&quot;">​</a></h1><p>Agent 装在每台要浏览的机器上，主动出站连 Hub。安装步骤见 <a href="/filebox/zh/guide/install-agent">部署 Agent</a>。</p><h2 id="状态与配置" tabindex="-1">状态与配置 <a class="header-anchor" href="#状态与配置" aria-label="Permalink to &quot;状态与配置&quot;">​</a></h2><ul><li>配置文件：<code>agent.toml</code>（<code>--init-config</code> 创建，权限 0600）。</li><li>状态目录默认在系统 data dir 下的 <code>filebox</code>（可用 <code>FILEBOX_AGENT_DATA_DIR</code>）。</li><li>根目录、钉选、合集经 UI 下发并持久化；坏的更新不会毁掉上一份好配置。</li><li>断线后永久重连，身份不变、不产生重复侧栏条目。</li><li>多实例必须使用不同的 <code>FILEBOX_AGENT_DATA_DIR</code>。</li></ul><h2 id="环境变量摘要" tabindex="-1">环境变量摘要 <a class="header-anchor" href="#环境变量摘要" aria-label="Permalink to &quot;环境变量摘要&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>含义</th></tr></thead><tbody><tr><td><code>FILEBOX_AGENT_HUB</code></td><td>Hub URL（<code>https://</code> / <code>wss://</code>）</td></tr><tr><td><code>FILEBOX_AGENT_TOKEN</code></td><td>Agent token</td></tr><tr><td><code>FILEBOX_AGENT_NAME</code></td><td>侧栏显示名</td></tr><tr><td><code>FILEBOX_AGENT_DATA_DIR</code></td><td>状态目录</td></tr><tr><td><code>FILEBOX_AGENT_AI_AGENTS_ENABLED</code></td><td>在此 Agent 上启用或禁用 AI Agents</td></tr><tr><td><code>FILEBOX_AGENT_AI_AGENTS_BACKEND</code></td><td>将 AI Agents 锁定到指定后端类型</td></tr><tr><td><code>FILEBOX_AGENT_HC</code></td><td>指定 hc 可执行文件路径（试验性后端；未设置时搜索 PATH）</td></tr><tr><td><code>FILEBOX_ALLOW_INSECURE_HUB</code></td><td>允许明文 Hub（仅开发）</td></tr><tr><td><code>FILEBOX_AGENT_SOFFICE</code> / <code>_DIR</code></td><td>LibreOffice（可选）</td></tr><tr><td><code>FILEBOX_AGENT_STATS_TTL_SECS</code></td><td>sysinfo 缓存 TTL（默认 60）</td></tr><tr><td><code>FILEBOX_AGENT_DIR_CACHE_RESTAT_COOLDOWN_MS</code></td><td>目录缓存 re-stat 冷却</td></tr></tbody></table><p>Office 相关上限见 <a href="./office">Office 预览</a>。</p><h2 id="experimental-hc-backend" tabindex="-1">试验性 hc 后端 <a class="header-anchor" href="#experimental-hc-backend" aria-label="Permalink to &quot;试验性 hc 后端 {#experimental-hc-backend}&quot;">​</a></h2><p>在 Agent 机器安装 <a href="https://github.com/herdrdev/herdr-core#install" target="_blank" rel="noreferrer">herdr-core</a>， 让 Filebox Agent 能找到 <code>hc</code>。在各自工作目录启动终端，用 <code>fb=名称</code> 或 <code>filebox=名称</code> 指定它在 Filebox 中的显示名称；只接入带这些标记的本地运行中终端：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fb=frontend</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Filebox=backend</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> t7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fb=review</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 接入已有终端，或修改它在 Filebox 中的名称</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> t7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fb=</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # 移除此标签，撤销接入</span></span></code></pre></div><p>将 <code>t7</code> 换成实际终端地址，<code>claude</code> 换成要运行的程序。 标签决定终端是否接入，里面运行编码代理、shell 或其他程序均可，不额外判断程序类型。 标签键不区分大小写：<code>fb</code>、<code>FB</code>、<code>filebox</code>、<code>Filebox</code>、<code>FILEBOX</code> 及混合大小写均可； 值是客户自定的名称，不是固定口令，空值或纯空白不接入。名称可包含中文或空格， 含空格时给整个标签加引号，例如 <code>--label &#39;fb=Code review&#39;</code>。 原来的 <code>filebox=ai-agent</code> 仍可接入，并保留 hc 终端原名；同时有两种标签时，优先使用 <code>fb</code> 的名称。 列表和详情保留终端 ID，同名或改名不会改变操作目标；刷新列表后更新名称，选中项和草稿不变。 这些名称不修改 hc 自身的终端名。撤销接入时，需删除所有受支持的标签，删除命令保留原键名大小写， 例如 <code>hc label t7 Filebox=</code> 删除 <code>Filebox=backend</code>，不会删除另一个 <code>fb</code> 或 <code>FILEBOX</code> 标签。</p><p>在 Agent Settings 选择 <strong>hc (experimental)</strong>；同时安装两种后端时，自动选择仍优先 Herdr。 <code>FILEBOX_AGENT_AI_AGENTS_BACKEND=hc</code> 可锁定选择。hc 沿用 Agent 进程的 hc session/config 环境， <code>hc connect</code> 可自动启动本地 core。状态只来自程序的 OSC 7501 报告，没有报告则显示 Unknown； prompt 审核链路不变。不接入未标记、已结束或远端机器的终端。取消不能撤回 hc 已接受的输入， 重试前请先检查输出。已验证 hc 0.1.17、API generation 1。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update</span></span></code></pre></div><p>校验校验和后原地替换。建议与 Hub、前端大版本一起升。</p><h2 id="可选能力开关" tabindex="-1">可选能力开关 <a class="header-anchor" href="#可选能力开关" aria-label="Permalink to &quot;可选能力开关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>配置入口</th></tr></thead><tbody><tr><td>Office 预览</td><td><a href="./office">Office 预览</a></td></tr><tr><td>Transfer</td><td>能力位 <code>temp_upload</code>；规则见 <a href="/filebox/zh/features/transfer">Transfer</a></td></tr></tbody></table><p>在 UI <strong>Settings</strong> 可确认连接状态与已启用 roots：</p><p><img src="`+t+'" alt="Settings"></p>',19)])])}const b=a(o,[["render",n]]);export{g as __pageData,b as default};
